import{z as i,x as s,o as e,c as d,q as n,j as t,D as A,d as l,s as r,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"持续学习收束","description":"","frontmatter":{"title":"持续学习收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-map.md","filePath":"llm/continual-map.md","lastUpdated":1791413859000}'),m={name:"llm/continual-map.md"};function p(c,E,D,u,f,h){const B=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=n('<h1 id="持续学习收束" tabindex="-1">持续学习收束 <a class="header-anchor" href="#持续学习收束" aria-label="Permalink to &quot;持续学习收束&quot;">​</a></h1><div class="epigraph"><p>上线的模型是一个过程，不是一件物品；持续学习的全部工程，是给这个过程装上证据、闸门与账本。</p><footer>—— 据 Kirkpatrick 等 2017、Rolnick 等 2019、De Lange 等 2021 整理</footer></div><p><a href="/llm/continual-production-cases">上一课</a>把生产环里实际会断的位置列成失败目录。本课把整门课收拢：三个单元各自回答了什么，机制之间怎么互相替换，以及拿到一个真实系统时从哪张表开始查。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的问题是一个选型问题：同样是「模型要跟上变化」，正则、回放、适配器、合并、在线更新、测试时训练，六条路在什么前提下选哪条？判据不在论文里，在系统的约束里：旧数据还留不留得住、能力能不能被隔离、更新要多久生效、延迟预算多大、合规口径多严。</p><p><span class="marginnote">可以把「模型要跟上变化」想象成给一栋盖好的楼做改造：回放是把旧图纸都留着、照着对齐；正则是规定「承重墙不能动」；适配器是加盖活动板房，不动主体；合并是把几次改造图拼成一张总图。选哪条路，先看旧图纸还在不在、住户能不能搬——对应旧数据可得性与隔离要求。</span></p><h3 id="三个单元的一条线" tabindex="-1">三个单元的一条线 <a class="header-anchor" href="#三个单元的一条线" aria-label="Permalink to &quot;三个单元的一条线&quot;">​</a></h3><p>基础机制单元给了问题定义与两条经典对策：<a href="/llm/continual-forgetting-mechanism">遗忘的机制</a>把遗忘拆成方向与步长，<a href="/llm/continual-ewc-family">参数正则</a>约束方向，<a href="/llm/continual-replay-buffer">回放缓冲</a>重混数据——这一对覆盖了「旧数据可得与不可得」两种前提。语言模型单元把机制换成工程载体：<a href="/llm/continual-lora-lifecycle">LoRA 生命周期</a>用冻结基座做结构性保护，<a href="/llm/continual-model-merge">模型合并</a>用向量组合绕开序列覆盖，<a href="/llm/continual-online-preference">在线偏好更新</a>把节奏压到流式，<a href="/llm/continual-test-time-training">测试时训练</a>把寿命压到单次请求。生产化单元给环装上外围：<a href="/llm/continual-drift-detection">漂移检测</a>定何时更新，<a href="/llm/continual-feedback-privacy">隐私与合规</a>定什么能进更新，<a href="/llm/continual-eval-protocol">评测协议</a>定更新怎么记分，<a href="/llm/continual-production-cases">失败目录</a>定环怎么排查。</p><p><span class="marginnote">整门课的机制可以排成一条「更新寿命」轴：测试时训练的请求级、在线偏好的天级、LoRA 生命周期的周级、合并的月级、全量重训的年级——寿命每降一档，验证与回滚的自动化要求就抬一级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型按四问走。<strong>数据侧</strong>：旧数据能留吗？能留且便宜，回放是默认起手；不能留（隐私、成本），正则或适配器隔离。<strong>能力侧</strong>：变化是局部行为还是全局知识？局部行为走适配器，阶段性固化走合并，全局知识过期的部分没有捷径，回到预训练配比。<strong>节奏侧</strong>：偏变快且反馈真，在线偏好环；变化只在单请求内，测试时训练；按月演进，快照加合并。<strong>治理侧</strong>：任何一条路上，漂移检测、隐私闸门、轨迹协议三件套不是可选项——它们是让「持续」两个字可以对外承诺的部分。</p>',11)),(e(),t(o,null,{default:A(()=>[r(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E6%A8%A1%E5%9E%8B%E8%A6%81%E8%B7%9F%E4%B8%8A%E5%8F%98%E5%8C%96%22%5D%20--%3E%20U1%5B%22%E5%9F%BA%E7%A1%80%E6%9C%BA%E5%88%B6%EF%BC%9A%E9%81%97%E5%BF%98%20%2F%20%E6%AD%A3%E5%88%99%20%2F%20%E5%9B%9E%E6%94%BE%22%5D%0A%20%20GOAL%20--%3E%20U2%5B%22%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%E8%BD%BD%E4%BD%93%EF%BC%9ALoRA%20%2F%20%E5%90%88%E5%B9%B6%20%2F%20%E5%9C%A8%E7%BA%BF%E5%81%8F%E5%A5%BD%20%2F%20TTT%22%5D%0A%20%20GOAL%20--%3E%20U3%5B%22%E7%94%9F%E4%BA%A7%E5%8C%96%EF%BC%9A%E6%A3%80%E6%B5%8B%20%2F%20%E9%9A%90%E7%A7%81%20%2F%20%E8%AF%84%E6%B5%8B%20%2F%20%E5%A4%B1%E8%B4%A5%E7%9B%AE%E5%BD%95%22%5D%0A%20%20U1%20--%3E%20Q1%7B%22%E6%97%A7%E6%95%B0%E6%8D%AE%E7%95%99%E5%BE%97%E4%BD%8F%E5%90%97%3F%22%7D%0A%20%20Q1%20--%3E%7C%E8%83%BD%7C%20REP%5B%22%E5%9B%9E%E6%94%BE%E4%B8%BA%E4%B8%BB%EF%BC%8C%E6%AD%A3%E5%88%99%E4%B8%BA%E8%BE%85%22%5D%0A%20%20Q1%20--%3E%7C%E4%B8%8D%E8%83%BD%7C%20REG%5B%22%E6%AD%A3%E5%88%99%E6%88%96%E9%80%82%E9%85%8D%E5%99%A8%E9%9A%94%E7%A6%BB%22%5D%0A%20%20REP%20--%3E%20LOOP%0A%20%20REG%20--%3E%20LOOP%5B%22%E7%94%9F%E4%BA%A7%E7%8E%AF%EF%BC%9A%E6%A3%80%E6%B5%8B%E8%A7%A6%E5%8F%91%E3%80%81%E9%97%B8%E9%97%A8%E5%85%A5%E3%80%81%E5%8D%8F%E8%AE%AE%E8%AE%B0%E5%88%86%22%5D%0A%20%20U2%20--%3E%20LOOP%0A%20%20U3%20--%3E%20LOOP%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"初学者容易以为选型是「挑一个最强的算法」。实际上六条机制针对的约束不同：旧数据留不留得住、变化是局部还是全局，这两个答案一变，最优选择就完全不同。先答约束、再挑机制；顺序反了，就会在一条不适用的路上拼命调参。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"把六条机制放在同一张账上，它们的交换关系就清楚了。回放买保护花的是数据账：存储、隐私、陈化。正则花的是可塑性账：新任务学得慢。适配器花的是架构账：路由、配对、服务复杂度。合并花的是验收账：每一步都可能静默亏空，全量探针不能省。在线更新花的是稳定性账：自指回路的偏置放大要靠环外审计压。TTT 花的是延迟账：把训练预算搬进请求。没有一条是免费的，工程师的判断花在「这个系统付得起哪笔账」上——这也是稳定性-可塑性 dilemma 在工程层的形态：它不是要被消灭的矛盾，而是要被记账的预算。",-1)),(e(),t(o,null,{default:A(()=>[r(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20M1%5B%22%E5%9B%9E%E6%94%BE%22%5D%20--%3E%7C%22%E6%95%B0%E6%8D%AE%E8%B4%A6%3A%20%E5%AD%98%E5%82%A8%2F%E9%9A%90%E7%A7%81%2F%E9%99%88%E5%8C%96%22%7C%20J%5B%22%E5%B7%A5%E7%A8%8B%E5%B8%88%E5%88%A4%E6%96%AD%3A%E4%BB%98%E5%BE%97%E8%B5%B7%E5%93%AA%E7%AC%94%E8%B4%A6%22%5D%0A%20%20M2%5B%22%E6%AD%A3%E5%88%99%22%5D%20--%3E%7C%22%E5%8F%AF%E5%A1%91%E6%80%A7%E8%B4%A6%3A%20%E6%96%B0%E4%BB%BB%E5%8A%A1%E5%AD%A6%E5%BE%97%E6%85%A2%22%7C%20J%0A%20%20M3%5B%22%E9%80%82%E9%85%8D%E5%99%A8%22%5D%20--%3E%7C%22%E6%9E%B6%E6%9E%84%E8%B4%A6%3A%20%E8%B7%AF%E7%94%B1%E4%B8%8E%E9%85%8D%E5%AF%B9%22%7C%20J%0A%20%20M4%5B%22%E5%90%88%E5%B9%B6%22%5D%20--%3E%7C%22%E9%AA%8C%E6%94%B6%E8%B4%A6%3A%20%E9%9D%99%E9%BB%98%E4%BA%8F%E7%A9%BA%E9%A3%8E%E9%99%A9%22%7C%20J%0A%20%20M5%5B%22%E5%9C%A8%E7%BA%BF%E6%9B%B4%E6%96%B0%22%5D%20--%3E%7C%22%E7%A8%B3%E5%AE%9A%E6%80%A7%E8%B4%A6%3A%20%E5%81%8F%E7%BD%AE%E6%94%BE%E5%A4%A7%22%7C%20J%0A%20%20M6%5B%22%E6%B5%8B%E8%AF%95%E6%97%B6%E8%AE%AD%E7%BB%83%22%5D%20--%3E%7C%22%E5%BB%B6%E8%BF%9F%E8%B4%A6%3A%20%E8%AE%AD%E7%BB%83%E8%BF%9B%E8%AF%B7%E6%B1%82%22%7C%20J%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">「稳定性-可塑性 dilemma」可以直译成「记性与学性的矛盾」：模型把旧任务记得越牢，就越难腾出容量学新任务；学新任务越快，旧的忘得越狠。工程上没有消灭这个矛盾的办法，只能像做预算一样，决定这个阶段多付哪一边。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程没有覆盖的几块要说清边界。机器遗忘的形式化保证与删除义务，只在本课程里给了工程口径，理论仍在演进。联邦持续学习——多端各自持续更新再聚合——把本课程的每个难题乘上参与方数量，未展开。Agent 的终身学习——记忆、技能与工具使用随经验积累——挂在 Agent 工程的课程里，与本课的权重更新是互补的两层。还有一块是评估的本体论困难：探针电池与滚动基准都在追赶「什么是好」，这个追赶没有终点。持续学习最终教会工程的不是某个算法，而是一个姿态：模型没有「完成态」，任何认为已经训完的团队，只是还没找到自己的漂移。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三个单元一条线：机制（遗忘/正则/回放）定义问题，载体（LoRA/合并/在线/TTT）给出工程形态，生产化（检测/隐私/评测/失败目录）让环可承诺。</li><li>选型四问：数据留得住吗、变化是局部还是全局、节奏多快、治理多严。</li><li>六条机制排成更新寿命轴，寿命每降一档，验证与回滚的自动化要求抬一级。</li><li>每条机制花一笔不同的账：数据、可塑性、架构、验收、稳定性、延迟；先看付得起哪笔。</li><li>检测、隐私、评测三件套是「持续」可以对外承诺的前提，不是可选项。</li><li>出处：Kirkpatrick 等 2017；Rolnick 等 2019；Hu 等 2021；Yadav 等 2023；Hardt 等 2016；De Lange 等 2021 综述。</li></ul>',5))])}const g=i(m,[["render",p]]);export{C as __pageData,g as default};
